// Prepare/Eval state for the CMSIS-NN float32 conv. When `enabled` is false,
// Eval is a no-op and the caller falls back to the reference path.
struct ConvF32State {
  bool enabled = false;
  int scratch_buffer_index = -1;
  int32_t scratch_buffer_size = 0;
  cmsis_nn_conv_params_f32 params;
  cmsis_nn_dims input_dims;
  cmsis_nn_dims filter_dims;
  cmsis_nn_dims bias_dims;
  cmsis_nn_dims output_dims;
};

