97	  TF_LITE_ENSURE_EQ(context, input->dims->size, 4);
98	  TF_LITE_ENSURE_EQ(context, filter->dims->size, 4);
99	  TF_LITE_ENSURE_EQ(context, output->dims->size, 4);
100	  // Equal batch size in input and output
101	  TF_LITE_ENSURE_EQ(context, input->dims->data[0], output->dims->data[0]);
102	  // Input channels should be an even multiple of filter channels
103	  TF_LITE_ENSURE(context, filter->dims->data[3] > 0);
104	  TF_LITE_ENSURE_EQ(context, input->dims->data[3] % filter->dims->data[3], 0);
105	  // Output channels should be an even multiple of the number of groups
106	  const int groups = input->dims->data[3] / filter->dims->data[3];
107	  TFLITE_DCHECK_EQ(output->dims->data[3] % groups, 0);
108	  // Bias size equal to output channels
109	  if (bias != nullptr) {
110	    TF_LITE_ENSURE(context, bias->dims->size == 1 || bias->dims->size == 4);
111	    TF_LITE_ENSURE_EQ(context, NumElements(bias->dims), output->dims->data[3]);
112	  }
113	
114	  // Initialize cmsis_nn dimensions
115	  cmsis_nn_dims input_dims;
116	  input_dims.n = input->dims->data[0];
117	  input_dims.h = input->dims->data[1];
118	  input_dims.w = input->dims->data[2];
119	  input_dims.c = input->dims->data[3];
120	
121	  cmsis_nn_dims filter_dims;
122	  filter_dims.n = 1;
123	  filter_dims.h = filter->dims->data[1];
124	  filter_dims.w = filter->dims->data[2];
125	  filter_dims.c = filter->dims->data[3];
126	
127	  cmsis_nn_dims output_dims;
128	  output_dims.n = output->dims->data[0];
129	  output_dims.h = output->dims->data[1];
130	  output_dims.w = output->dims->data[2];
131	  output_dims.c = output->dims->data[3];
132	
133	  if (input->type == kTfLiteInt8 || input->type == kTfLiteInt16) {
134	    const int num_channels = filter->dims->data[kConvQuantizedDimension];
135	    data->reference_op_data.per_channel_output_multiplier =
