176	      }
177	      row_sums[c] = s;
178	    }
179	    data->reference_op_data.hybrid_row_sums = row_sums;
180	
181	    const int filter_h = filter->dims->data[1];
182	    const int filter_w = filter->dims->data[2];
183	    const int input_depth = input->dims->data[3];
184	    const int patch_size = filter_h * filter_w * input_depth;
185	    const int tile_w = kHybridConvTileWidth;
186	    TF_LITE_ENSURE_STATUS(context->RequestScratchBufferInArena(
