200	  if (input->type == kTfLiteInt8 ||
201	      (input->type == kTfLiteInt16 &&
202	       (bias_type == kTfLiteInt64 || bias_type == kTfLiteNoType))) {
203	    // Initialize cmsis_nn convolution parameters
204	    cmsis_nn_conv_params conv_params;
205	    conv_params.input_offset = -input->params.zero_point;
206	    conv_params.output_offset = output->params.zero_point;
207	    conv_params.stride.h = params.stride_height;
208	    conv_params.stride.w = params.stride_width;
209	    conv_params.dilation.h = params.dilation_height_factor;
210	    conv_params.dilation.w = params.dilation_width_factor;
211	    conv_params.padding.h = data->reference_op_data.padding.height;
212	    conv_params.padding.w = data->reference_op_data.padding.width;
213	    conv_params.activation.min = data->reference_op_data.output_activation_min;
214	    conv_params.activation.max = data->reference_op_data.output_activation_max;
215	
216	    if (input->type == kTfLiteInt8) {
217	      buf_size = arm_convolve_wrapper_s8_get_buffer_size(
218	          &conv_params, &input_dims, &filter_dims, &output_dims);
219	    } else if (input->type == kTfLiteInt16) {
220	      TF_LITE_ENSURE_EQ(context, input->params.zero_point, 0);
