231	    }
232	  }
233	
234	  micro_context->DeallocateTempTfLiteTensor(output);
235	  micro_context->DeallocateTempTfLiteTensor(input);
236	  micro_context->DeallocateTempTfLiteTensor(filter);
237	  if (bias != nullptr) {
238	    micro_context->DeallocateTempTfLiteTensor(bias);
239	  }
240	
241	  return kTfLiteOk;
242	}
