290	template <typename ActType, typename BiasType, TfLiteType type>
291	TfLiteStatus EvalQuantizedPerChannel(TfLiteContext* context, TfLiteNode* node,
292	                                     const TfLiteConvParams& params,
293	                                     const OpData& data,
294	                                     const TfLiteEvalTensor* input,
295	                                     const TfLiteEvalTensor* filter,
296	                                     const TfLiteEvalTensor* bias,
297	                                     TfLiteEvalTensor* output) {
298	  cmsis_nn_conv_params conv_params;
299	  conv_params.dilation.h = params.dilation_height_factor;
300	  conv_params.dilation.w = params.dilation_width_factor;
301	
302	  // Initialize cmsis_nn convolution parameters
303	  conv_params.input_offset = -data.reference_op_data.input_zero_point;
304	  conv_params.output_offset = data.reference_op_data.output_zero_point;
305	  conv_params.stride.h = params.stride_height;
306	  conv_params.stride.w = params.stride_width;
307	  conv_params.padding.h = data.reference_op_data.padding.height;
308	  conv_params.padding.w = data.reference_op_data.padding.width;
309	  conv_params.activation.min = data.reference_op_data.output_activation_min;
310	  conv_params.activation.max = data.reference_op_data.output_activation_max;
311	
312	  // Initialize cmsis_nn per channel quantization parameters
313	  cmsis_nn_per_channel_quant_params quant_params;
314	  quant_params.multiplier = const_cast<int32_t*>(
315	      data.reference_op_data.per_channel_output_multiplier);
316	  quant_params.shift =
317	      const_cast<int32_t*>(data.reference_op_data.per_channel_output_shift);
318	
319	  // Initialize cmsis_nn dimension structs, consistency is checked in the
320	  // prepare stage
321	  cmsis_nn_dims input_dims;
322	  input_dims.n = input->dims->data[0];
323	  input_dims.h = input->dims->data[1];
324	  input_dims.w = input->dims->data[2];
325	  input_dims.c = input->dims->data[3];
326	
327	  cmsis_nn_dims filter_dims;
328	  filter_dims.n = 1;
329	  filter_dims.h = filter->dims->data[1];
330	  filter_dims.w = filter->dims->data[2];
331	  filter_dims.c = filter->dims->data[3];
332	
333	  cmsis_nn_dims bias_dims;
334	  bias_dims.n = 1;
335	  bias_dims.h = 1;
336	  bias_dims.w = 1;
337	  bias_dims.c = output->dims->data[3];
338	
339	  cmsis_nn_dims output_dims;
340	  output_dims.n = output->dims->data[0];
341	  output_dims.h = output->dims->data[1];
342	  output_dims.w = output->dims->data[2];
343	  output_dims.c = output->dims->data[3];
344	
345	  // Initialize cmsis_nn context
346	  cmsis_nn_context ctx;
347	  ctx.buf = nullptr;
348	  ctx.size = 0;
349	
350	  if (data.buffer_idx > -1) {
351	    ctx.buf = context->GetScratchBuffer(context, data.buffer_idx);
352	    // Note: ctx.size is currently not used in cmsis_nn.
353	    // The buffer should be allocated in the prepare function through
354	    // the corresponding arm_convolve_wrapper_[type]_get_buffer_size
355	  }
356	
357	  // arm_convolve_wrapper_[type] dispatches the optimized kernel accordingly
358	  // with the parameters passed
359	  TFLITE_DCHECK_EQ(
360	      convolve_wrapper(
361	          &ctx, &conv_params, &quant_params, &input_dims,
362	          tflite::micro::GetTensorData<ActType>(input), &filter_dims,
363	          tflite::micro::GetTensorData<int8_t>(filter), &bias_dims,
