570	TfLiteStatus Eval(TfLiteContext* context, TfLiteNode* node) {
571	  const TfLiteEvalTensor* input =
572	      tflite::micro::GetEvalInput(context, node, kConvInputTensor);
573	  const TfLiteEvalTensor* filter =
574	      tflite::micro::GetEvalInput(context, node, kConvWeightsTensor);
575	  const TfLiteEvalTensor* bias =
576	      (NumInputs(node) == 3)
577	          ? tflite::micro::GetEvalInput(context, node, kConvBiasTensor)
578	          : nullptr;
579	  TfLiteEvalTensor* output =
580	      tflite::micro::GetEvalOutput(context, node, kConvOutputTensor);
581	
582	  TFLITE_DCHECK(node->builtin_data != nullptr);
583	  const auto& params =
584	      *(reinterpret_cast<TfLiteConvParams*>(node->builtin_data));
585	  TFLITE_DCHECK(node->user_data != nullptr);
586	  const OpData& data = *(static_cast<const OpData*>(node->user_data));
587	
588	  TF_LITE_ENSURE_EQ(context, input->type, output->type);
589	  TF_LITE_ENSURE_MSG(
590	      context,
591	      input->type == filter->type ||
592	          (input->type == kTfLiteFloat32 && filter->type == kTfLiteInt8) ||
593	          (input->type == kTfLiteInt16 && filter->type == kTfLiteInt8) ||
594	          (input->type == kTfLiteInt8 && filter->type == kTfLiteInt4),
595	      "Input/filter type combination not supported on TFLite Micro.");
596	
597	  switch (input->type) {  // Already know in/out types are same.
598	    case kTfLiteFloat32: {
599	      if (data.reference_op_data.is_hybrid) {
600	        return ConvEvalHybrid(context, params, data.reference_op_data,
601	                              input, filter, bias, output);
602	      }
603	#if defined(CMSIS_NN)
604	      if (cmsis_nn::EvalConvF32(context, input, filter, bias, output,
605	                                data.conv_f32)) {
606	        break;
607	      }
608	#endif
609	      tflite::reference_ops::Conv(
610	          ConvParamsFloat(params, data.reference_op_data),
611	          tflite::micro::GetTensorShape(input),
612	          tflite::micro::GetTensorData<float>(input),
613	          tflite::micro::GetTensorShape(filter),
614	          tflite::micro::GetTensorData<float>(filter),
615	          tflite::micro::GetTensorShape(bias),
616	          tflite::micro::GetOptionalTensorData<float>(bias),
617	          tflite::micro::GetTensorShape(output),
618	          tflite::micro::GetTensorData<float>(output),
619	          tflite::micro::GetTensorShape(nullptr), nullptr);
620	      break;
621	    }
622	    case kTfLiteInt8: {
623	      switch (filter->type) {
624	        case kTfLiteInt4: {
625	          return EvalQuantizedPerChannel<int8_t, int32_t, kTfLiteInt4>(
626	              context, node, params, data, input, filter, bias, output);
627	        }
628	        case kTfLiteInt8: {
629	          return EvalQuantizedPerChannel<int8_t, int32_t, kTfLiteInt8>(
630	              context, node, params, data, input, filter, bias, output);
631	        }
632	        default: {
633	          MicroPrintf("Filter type %s (%d) not supported.",
634	                      TfLiteTypeGetName(filter->type), filter->type);
635	          return kTfLiteError;
636	        }
637	      }
638	      break;
639	    }
640	    case kTfLiteInt16: {
641	      if (bias == nullptr || bias->type == kTfLiteInt64) {
642	        return EvalQuantizedPerChannel<int16_t, int64_t, kTfLiteInt16>(
643	            context, node, params, data, input, filter, bias, output);
644	      } else if (bias->type == kTfLiteInt32) {
645	        reference_integer_ops::ConvPerChannel(
646	            ConvParamsQuantized(params, data.reference_op_data),
647	            data.reference_op_data.per_channel_output_multiplier,
648	            data.reference_op_data.per_channel_output_shift,
649	            tflite::micro::GetTensorShape(input),
650	            tflite::micro::GetTensorData<int16_t>(input),
651	            tflite::micro::GetTensorShape(filter),
652	            tflite::micro::GetTensorData<int8_t>(filter),
653	            tflite::micro::GetTensorShape(bias),
654	            tflite::micro::GetOptionalTensorData<std::int32_t>(bias),
655	            tflite::micro::GetTensorShape(output),
656	            tflite::micro::GetTensorData<int16_t>(output));
657	      } else {
658	        MicroPrintf("Bias type %s (%d) not supported.",
659	                    TfLiteTypeGetName(bias->type), bias->type);
660	        return kTfLiteError;
661	      }
662	      break;
663	    }
664	    default:
665	      MicroPrintf("Type %s (%d) not supported.", TfLiteTypeGetName(input->type),
666	                  input->type);
667	      return kTfLiteError;
668	  }
669	
670	  return kTfLiteOk;
671	}
