37	// GRU equations (reset-after variant, Keras default):
38	//   z = sigmoid(xw[0:h] + hw[0:h])
39	//   r = sigmoid(xw[h:2h] + hw[h:2h])
40	//   n = tanh(xw[2h:3h] + r * hw[2h:3h])
41	//   h_new = (1 - z) * n + z * h_prev
42	//
43	// Weight layout: [3*hidden, dim] with z/r/n gates stacked vertically.
44	
45	#if !(defined(XTENSA) && defined(HIFI4))
46	static inline float Sigmoid(float x) { return 1.0f / (1.0f + std::exp(-x)); }
47	#endif
48	
49	static inline size_t AlignUp4(size_t v) { return (v + 3) & ~static_cast<size_t>(3); }
50	
51	void FloatMatVec(int rows, int cols, const float* matrix, const float* vec,
52	                 const float* bias, float* output) {
53	#if defined(CMSIS_NN)
54	  // MVE-F: vec[1xcols] * matrix[rowsxcols]^T + bias -> output[rows].
55	  if (arm_nn_mat_mult_nt_t_f32(vec, matrix, bias, output, /*lhs_rows=*/1,
56	                               /*rhs_rows=*/rows, /*rhs_cols=*/cols,
57	                               /*row_address_offset=*/rows, -FLT_MAX,
58	                               FLT_MAX) == ARM_CMSIS_NN_SUCCESS) {
59	    return;
60	  }
61	#endif
62	  for (int i = 0; i < rows; ++i) {
63	    float sum = bias[i];
64	    for (int j = 0; j < cols; ++j) {
65	      sum += vec[j] * matrix[i * cols + j];
66	    }
67	    output[i] = sum;
68	  }
69	}
