71	void SymmetricQuantize(const float* input, int size, int8_t* output,
72	                       float* scale) {
73	  float min_val = input[0];
74	  float max_val = input[0];
75	  for (int i = 1; i < size; ++i) {
76	    if (input[i] < min_val) min_val = input[i];
77	    if (input[i] > max_val) max_val = input[i];
78	  }
79	  const float range = std::max(std::abs(min_val), std::abs(max_val));
80	  if (range == 0.0f) {
81	    *scale = 1.0f;
82	    std::memset(output, 0, size * sizeof(int8_t));
83	    return;
84	  }
85	  *scale = range / 127.0f;
86	  const float inv_scale = 127.0f / range;
87	  for (int i = 0; i < size; ++i) {
88	    int32_t v = static_cast<int32_t>(input[i] * inv_scale +
89	                                     (input[i] >= 0.0f ? 0.5f : -0.5f));
90	    v = v < -127 ? -127 : (v > 127 ? 127 : v);
91	    output[i] = static_cast<int8_t>(v);
92	  }
93	}
