95	void HybridMatVec(int rows, int cols, const int8_t* matrix, float filter_scale,
96	                  const float* vec, const float* bias, float* output,
97	                  int8_t* quantized_vec, int32_t* acc_buf) {
98	  float input_scale;
99	  SymmetricQuantize(vec, cols, quantized_vec, &input_scale);
100	
101	#if defined(CMSIS_NN)
102	  std::memset(acc_buf, 0, rows * sizeof(int32_t));
103	  arm_nn_mat_mult_nt_t_s8_s32(quantized_vec, matrix, acc_buf, 1, cols, rows, 0,
104	                              1);
105	  const float combined_scale = input_scale * filter_scale;
106	  for (int i = 0; i < rows; ++i) {
107	    output[i] = static_cast<float>(acc_buf[i]) * combined_scale + bias[i];
108	  }
109	#elif defined(XTENSA) && defined(HIFI4)
110	  if ((cols & 3) == 0) {
111	    alignas(8) int8_t zero_bias[192] = {};
112	    xa_nn_matXvec_8x8_32(
113	        acc_buf,
114	        const_cast<int8_t*>(matrix), nullptr,
115	        quantized_vec, nullptr,
116	        zero_bias,
117	        rows, cols, 0, cols, 0, 0, 0);
118	    const float combined_scale = input_scale * filter_scale;
119	    for (int i = 0; i < rows; ++i) {
120	      output[i] = static_cast<float>(acc_buf[i]) * combined_scale + bias[i];
121	    }
122	  } else {
123	    for (int i = 0; i < rows; ++i) {
124	      int32_t acc = 0;
125	      for (int j = 0; j < cols; ++j) {
126	        acc += static_cast<int32_t>(quantized_vec[j]) *
127	               static_cast<int32_t>(matrix[i * cols + j]);
128	      }
129	      output[i] = static_cast<float>(acc) * input_scale * filter_scale + bias[i];
130	    }
131	  }
132	#else
133	  for (int i = 0; i < rows; ++i) {
134	    int32_t acc = 0;
135	    for (int j = 0; j < cols; ++j) {
136	      acc += static_cast<int32_t>(quantized_vec[j]) *
137	             static_cast<int32_t>(matrix[i * cols + j]);
138	    }
139	    output[i] = static_cast<float>(acc) * input_scale * filter_scale + bias[i];
140	  }
141	#endif
142	}
