144	void ApplyGruGates(int n_output, const float* scratch_xw,
145	                   const float* scratch_hw, const float* h_prev,
146	                   float* h_new) {
147	#if defined(XTENSA) && defined(HIFI4)
148	  constexpr int kMax = 64;
149	  float tmp[kMax];
150	  float z_vec[kMax];
151	  float r_vec[kMax];
152	  float n_vec[kMax];
153	  // z = sigmoid(xw[0:h] + hw[0:h])
154	  for (int i = 0; i < n_output; ++i)
155	    tmp[i] = scratch_xw[i] + scratch_hw[i];
156	  xa_nn_vec_sigmoid_f32_f32(z_vec, tmp, n_output);
157	  // r = sigmoid(xw[h:2h] + hw[h:2h])
158	  for (int i = 0; i < n_output; ++i)
159	    tmp[i] = scratch_xw[n_output + i] + scratch_hw[n_output + i];
160	  xa_nn_vec_sigmoid_f32_f32(r_vec, tmp, n_output);
161	  // n = tanh(xw[2h:3h] + r * hw[2h:3h])
162	  for (int i = 0; i < n_output; ++i)
