180	void GruCellStep(int n_input, int n_output, const float* input,
181	                 const float* h_prev, const float* input_kernel,
182	                 const float* input_bias, const float* recurrent_kernel,
183	                 const float* recurrent_bias, float* h_new, float* scratch_xw,
184	                 float* scratch_hw) {
