207	// Bidirectional GRU custom op for TFLM.
208	// Input tensors:
209	//   0: input               [batch, seq_len, input_dim] or [seq_len, input_dim]
210	//   1-4: fw_input_kernel, fw_input_bias, fw_recurrent_kernel, fw_recurrent_bias
211	//   5-8: bw_input_kernel, bw_input_bias, bw_recurrent_kernel, bw_recurrent_bias
212	// Output:
213	//   0: [seq_len, 2*hidden] — forward in left half, backward in right half
214	
215	constexpr int kInputTensor = 0;
216	constexpr int kFwInputKernel = 1;
217	constexpr int kFwInputBias = 2;
218	constexpr int kFwRecurrentKernel = 3;
219	constexpr int kFwRecurrentBias = 4;
220	constexpr int kBwInputKernel = 5;
221	constexpr int kBwInputBias = 6;
222	constexpr int kBwRecurrentKernel = 7;
223	constexpr int kBwRecurrentBias = 8;
224	constexpr int kNumInputs = 9;
225	constexpr int kOutputTensor = 0;
226	constexpr int kNumOutputs = 1;
