228	struct BiGruOpData {
229	  int scratch_index;
230	  bool is_hybrid;
231	  int hybrid_quant_offset;
232	  int hybrid_acc_offset;
233	  float fw_ik_scale;
234	  float fw_rk_scale;
235	  float bw_ik_scale;
236	  float bw_rk_scale;
237	};
