239	void* BiGruInit(TfLiteContext* context, const char* buffer, size_t length) {
240	  TFLITE_DCHECK(context->AllocatePersistentBuffer != nullptr);
241	  return context->AllocatePersistentBuffer(context, sizeof(BiGruOpData));
242	}
