244	TfLiteStatus BiGruPrepare(TfLiteContext* context, TfLiteNode* node) {
245	  TF_LITE_ENSURE_EQ(context, NumInputs(node), kNumInputs);
246	  TF_LITE_ENSURE_EQ(context, NumOutputs(node), kNumOutputs);
247	
248	  MicroContext* micro_context = GetMicroContext(context);
249	
250	  TfLiteTensor* input =
251	      micro_context->AllocateTempInputTensor(node, kInputTensor);
252	  TF_LITE_ENSURE(context, input != nullptr);
253	  TF_LITE_ENSURE(context, input->dims->size == 2 || input->dims->size == 3);
254	
255	  TfLiteTensor* fw_ik =
256	      micro_context->AllocateTempInputTensor(node, kFwInputKernel);
257	  TF_LITE_ENSURE(context, fw_ik != nullptr);
258	
259	  TfLiteTensor* fw_rk =
260	      micro_context->AllocateTempInputTensor(node, kFwRecurrentKernel);
261	  TF_LITE_ENSURE(context, fw_rk != nullptr);
262	  const int n_output = fw_rk->dims->data[1];
263	
264	  const int ndims = input->dims->size;
265	  const int n_input =
266	      (ndims == 3) ? input->dims->data[2] : input->dims->data[1];
267	  const int seq_len =
268	      (ndims == 3) ? input->dims->data[1] : input->dims->data[0];
269	
270	  BiGruOpData* op_data = reinterpret_cast<BiGruOpData*>(node->user_data);
271	  op_data->is_hybrid = (fw_ik->type == kTfLiteInt8);
272	
273	  // Scratch layout (all float region first, then hybrid int8/int32):
274	  //   [h_state: n_output] [scratch_xw: 3*n_output] [scratch_hw: 3*n_output]
275	  //   [fw_output: seq_len*n_output]
276	  //   --- hybrid only (4-byte aligned) ---
277	  //   [quant_buf: max(n_input, n_output) int8, padded to 4-byte]
278	  //   [acc_buf: 3*n_output int32]
279	  size_t float_bytes =
280	      static_cast<size_t>(7 * n_output + seq_len * n_output) * sizeof(float);
281	  size_t scratch_size = float_bytes;
282	
283	  if (op_data->is_hybrid) {
284	    const int max_vec = std::max(n_input, n_output);
285	    size_t quant_bytes = AlignUp4(max_vec * sizeof(int8_t));
286	    op_data->hybrid_quant_offset = static_cast<int>(float_bytes);
287	    op_data->hybrid_acc_offset =
288	        static_cast<int>(float_bytes + quant_bytes);
289	    scratch_size = float_bytes + quant_bytes + 3 * n_output * sizeof(int32_t);
290	
291	    auto get_scale = [](TfLiteTensor* t) -> float {
292	      const auto* aq =
293	          static_cast<TfLiteAffineQuantization*>(t->quantization.params);
294	      return aq->scale->data[0];
295	    };
296	
297	    op_data->fw_ik_scale = get_scale(fw_ik);
298	    op_data->fw_rk_scale = get_scale(fw_rk);
299	
300	    TfLiteTensor* bw_ik =
301	        micro_context->AllocateTempInputTensor(node, kBwInputKernel);
302	    TfLiteTensor* bw_rk =
303	        micro_context->AllocateTempInputTensor(node, kBwRecurrentKernel);
304	    op_data->bw_ik_scale = get_scale(bw_ik);
305	    op_data->bw_rk_scale = get_scale(bw_rk);
306	    micro_context->DeallocateTempTfLiteTensor(bw_ik);
307	    micro_context->DeallocateTempTfLiteTensor(bw_rk);
308	  }
309	
310	  TF_LITE_ENSURE_STATUS(context->RequestScratchBufferInArena(
311	      context, scratch_size, &op_data->scratch_index));
312	
313	  micro_context->DeallocateTempTfLiteTensor(input);
314	  micro_context->DeallocateTempTfLiteTensor(fw_ik);
315	  micro_context->DeallocateTempTfLiteTensor(fw_rk);
316	
317	  return kTfLiteOk;
318	}
