320	TfLiteStatus BiGruEval(TfLiteContext* context, TfLiteNode* node) {
321	  const BiGruOpData* op_data =
322	      reinterpret_cast<const BiGruOpData*>(node->user_data);
323	
324	  const TfLiteEvalTensor* input =
325	      tflite::micro::GetEvalInput(context, node, kInputTensor);
326	  const TfLiteEvalTensor* fw_ik =
327	      tflite::micro::GetEvalInput(context, node, kFwInputKernel);
328	  const TfLiteEvalTensor* fw_ib =
329	      tflite::micro::GetEvalInput(context, node, kFwInputBias);
330	  const TfLiteEvalTensor* fw_rk =
331	      tflite::micro::GetEvalInput(context, node, kFwRecurrentKernel);
332	  const TfLiteEvalTensor* fw_rb =
333	      tflite::micro::GetEvalInput(context, node, kFwRecurrentBias);
334	  const TfLiteEvalTensor* bw_ik =
335	      tflite::micro::GetEvalInput(context, node, kBwInputKernel);
336	  const TfLiteEvalTensor* bw_ib =
337	      tflite::micro::GetEvalInput(context, node, kBwInputBias);
338	  const TfLiteEvalTensor* bw_rk =
339	      tflite::micro::GetEvalInput(context, node, kBwRecurrentKernel);
340	  const TfLiteEvalTensor* bw_rb =
341	      tflite::micro::GetEvalInput(context, node, kBwRecurrentBias);
342	  TfLiteEvalTensor* output =
343	      tflite::micro::GetEvalOutput(context, node, kOutputTensor);
344	
345	  const int ndims = input->dims->size;
346	  const int seq_len =
347	      (ndims == 3) ? input->dims->data[1] : input->dims->data[0];
348	  const int n_input =
349	      (ndims == 3) ? input->dims->data[2] : input->dims->data[1];
350	  const int n_output = fw_rk->dims->data[1];
351	
352	  const float* input_data = tflite::micro::GetTensorData<float>(input);
353	  float* output_data = tflite::micro::GetTensorData<float>(output);
354	
355	  uint8_t* raw_scratch = reinterpret_cast<uint8_t*>(
356	      context->GetScratchBuffer(context, op_data->scratch_index));
357	  float* h_state = reinterpret_cast<float*>(raw_scratch);
358	  float* scratch_xw = h_state + n_output;
359	  float* scratch_hw = scratch_xw + 3 * n_output;
360	  float* fw_output = scratch_hw + 3 * n_output;
361	
362	  int8_t* quant_buf = nullptr;
363	  int32_t* acc_buf = nullptr;
364	  if (op_data->is_hybrid) {
365	    quant_buf = reinterpret_cast<int8_t*>(
366	        raw_scratch + op_data->hybrid_quant_offset);
367	    acc_buf = reinterpret_cast<int32_t*>(
368	        raw_scratch + op_data->hybrid_acc_offset);
369	  }
370	
371	  // --- Forward pass → fw_output[seq_len, n_output] ---
372	  std::memset(h_state, 0, n_output * sizeof(float));
373	  for (int t = 0; t < seq_len; ++t) {
374	    const float* x_t = input_data + t * n_input;
375	    float* out_t = fw_output + t * n_output;
376	    if (op_data->is_hybrid) {
377	      GruCellStepHybrid(
378	          n_input, n_output, x_t, h_state,
379	          tflite::micro::GetTensorData<int8_t>(fw_ik), op_data->fw_ik_scale,
380	          tflite::micro::GetTensorData<float>(fw_ib),
381	          tflite::micro::GetTensorData<int8_t>(fw_rk), op_data->fw_rk_scale,
382	          tflite::micro::GetTensorData<float>(fw_rb), out_t, scratch_xw,
383	          scratch_hw, quant_buf, acc_buf);
384	    } else {
385	      GruCellStep(n_input, n_output, x_t, h_state,
386	                  tflite::micro::GetTensorData<float>(fw_ik),
387	                  tflite::micro::GetTensorData<float>(fw_ib),
388	                  tflite::micro::GetTensorData<float>(fw_rk),
389	                  tflite::micro::GetTensorData<float>(fw_rb), out_t,
390	                  scratch_xw, scratch_hw);
391	    }
392	    std::memcpy(h_state, out_t, n_output * sizeof(float));
393	  }
394	
395	  // Copy forward results to left half of output [seq_len, 2*n_output]
396	  for (int t = 0; t < seq_len; ++t) {
397	    std::memcpy(output_data + t * 2 * n_output, fw_output + t * n_output,
398	                n_output * sizeof(float));
399	  }
400	
401	  // --- Backward pass → right half of output ---
402	  std::memset(h_state, 0, n_output * sizeof(float));
403	  for (int t = 0; t < seq_len; ++t) {
404	    int src_t = seq_len - 1 - t;
405	    const float* x_t = input_data + src_t * n_input;
406	    float* out_t = output_data + src_t * 2 * n_output + n_output;
407	    if (op_data->is_hybrid) {
408	      GruCellStepHybrid(
409	          n_input, n_output, x_t, h_state,
410	          tflite::micro::GetTensorData<int8_t>(bw_ik), op_data->bw_ik_scale,
411	          tflite::micro::GetTensorData<float>(bw_ib),
412	          tflite::micro::GetTensorData<int8_t>(bw_rk), op_data->bw_rk_scale,
413	          tflite::micro::GetTensorData<float>(bw_rb), out_t, scratch_xw,
414	          scratch_hw, quant_buf, acc_buf);
415	    } else {
416	      GruCellStep(n_input, n_output, x_t, h_state,
417	                  tflite::micro::GetTensorData<float>(bw_ik),
418	                  tflite::micro::GetTensorData<float>(bw_ib),
419	                  tflite::micro::GetTensorData<float>(bw_rk),
420	                  tflite::micro::GetTensorData<float>(bw_rb), out_t,
421	                  scratch_xw, scratch_hw);
422	    }
423	    std::memcpy(h_state, out_t, n_output * sizeof(float));
424	  }
425	
426	  return kTfLiteOk;
427	}
